Here are the bounded contexts: 
```json
{
  "bounded contexts": {
    "Community Events": {
      "derived from": "Community Subdomain",
      "objects": [
        "Seed Exchange",
        "Harvest Donor",
        "Event Attendee",
        "Garden Fair",
        "Harvest Share Program",
        "Harvest Donation",
        "Agriculture Program"
      ],
      "name changes": [
        "City Resident -> Harvest Donor and Event Attendee"
      ]
    },
    "Volunteering": {
      "derived from": "Volunteering Subdomain",
      "objects": [
        "Volunteer",
        "Maintenance Day",
        "Community Compost"
      ],
      "name changes": [
        "Compost -> Community Compost"
      ]
    },
    "Garden Coordination": {
      "derived from": "Garden Coordination Subdomain",
      "objects": [
        "Garden Coordinator",
        "End Of Season Report",
        "Garden Inspection",
        "Funding"
      ],
      "name changes": []
    },
    "Gardening": {
      "derived from": "Gardening Subdomain",
      "objects": [
        "Gardener",
        "Plot Application",
        "Pest Issue Report",
        "Garden Plot",
        "Crop",
        "Plot Assignment List",
        "Compost"
      ],
      "name changes": [
        "City Resident -> Gardener",
        "Compost -> Personal Compost"
      ]
    }
  }
}
```
